        mail = str(e.get('ibanEmail') or '').strip()
        typ = str(e.get('communicationType') or '').strip().lower()
        if mail and '@' in mail and typ != 'phone':
            vars['email_state'] = 'ok'
            vars['email_addr'] = mail
            local, _, dom = mail.partition('@')
            odd = len(local) > 14 or bool(re.search(r'\d', local)) or len(re.findall(r'[._\-]', local)) > 1
            if odd:
                dn = dom.split('.')[0]
                dn = 'Gmail' if dn.lower() == 'gmail' else dn
                vars['email_spoken'] = local[0] + ' ile başlayan ' + dn + ' adresiniz'
            else:
