        else:
            vars['email_state'] = 'none'
    else:
        vars['email_state'] = 'error'
except Exception:
    vars['route'] = 'error'
    vars['email_state'] = vars.get('email_state') or 'error'
'''

RESOLVE_CODE = COMMON + r'''
try:
    said = str(vars.get('card_said') or '')
    vars['card_said'] = 'consumed'
    allc = jl('all_cards')
    main = jl('main_cards')
    stage = str(vars.get('sel_stage') or 'name')
    pool = jl('sel_pool') if stage in ('last4', 'last6', 'full') else allc
    dg = said_digits(said)
    def fail(msg):
        t = int(vars.get('sel_tries') or 0) + 1
        vars['sel_tries'] = str(t)
