            vars['sel_pool'] = json.dumps(hits, ensure_ascii=False)
            if len(dgs) >= 15:
                fail('Söylediğiniz numarayla eşleşen tek bir kart bulamadım. Kart numaranızı tekrar söyler misiniz?')
            elif len(dgs) >= 6:
