EMAIL_Q = r'''
try:
    sp = str(vars.get('email_spoken') or '')
    if sp.endswith(' adresi'):
        vars['email_spoken_q'] = sp[:-len(' adresi')] + ' adresine'
    elif sp:
        vars['email_spoken_q'] = sp + 'e'
    else:
        vars['email_spoken_q'] = 'kayıtlı e-posta adresinize'
except Exception:
    vars['email_spoken_q'] = 'kayıtlı e-posta adresinize'
'''


def all_codes(wf):
    out = {}
    for k, n in list(wf["nodes"].items()) + list(wf["global_nodes"].items()):
        for a in n.get("pre_actions", []):
            fn = a["function"]
            if fn["handler"] == "__function__:code_exec":
                out[k] = fn["parameters"]["properties"]["code"]["default"]
            for h in ("pre_process_code", "post_process_code"):
                if a.get(h):
                    out[k + ":" + h] = a[h]
    return out


def selftest():
    wf = build("https://mock.example/voice/v1")
    codes = all_codes(wf)
    for k, src in codes.items():
        assert "{{" not in src and "}}" not in src, k
        compile(src, k, "exec")
    fx = json.load(open(pathlib.Path(sys.argv[2] if len(sys.argv) > 2 else
                                     r"C:/Users/loseu/Desktop/FreyaBank-Ekstre-Borc/test-environment/test-customers.json"), encoding="utf-8"))
    cust = {x["customerNo"]: x for x in fx["customers"]}
    def run(key, v, config=None, result=None):
        exec(codes[key], {"vars": v, "config": config, "result": result})
    def call(prefix, svc, cno, key=None, week=None):
        s = cust[cno]["services"].get(svc)
        e = s if key is None else (s or {}).get(key)
        if week is not None and e is not None:
            e = e.get(str(week))
        if e is None:
            return {}
        r = e["response"]
        return {prefix + "_data": r.get("data", ""), prefix + "_rc": r["result"]["returnCode"]}
    def start(cno, now="2026-10-12T10:30:00+03:00"):
        v = {"customerNumber": cno, "now": now}
        run("init", v)
