        run("cards_list:pre_process_code", v, cfg)
        assert cfg["body"]["data"]["customerNo"] == cno, cfg
        v.update(call("cl", "cards.list", cno)); v.update(call("em", "contact.email.get", cno))
        run("after_list", v)
        return v
