"""Generator for the Freya Bank statement-debt agent (final case folder FreyaBank-Ekstre-Borc).

    python out/gen_freyabank_ekstre_borc.py <tool base url ending in /voice/v1>   writes out/freyabank-ekstre-borc.workflow.json
    python out/gen_freyabank_ekstre_borc.py --selftest                            execs every code snippet on sample inputs

Every rule, sentence and value comes from the case folder's sources (latest record governs) and the service contract.
"""
import json, pathlib, sys

OUT = pathlib.Path(__file__).resolve().parent / "freyabank-ekstre-borc.workflow.json"

# ---------------------------------------------------------------- fixed sentences from the sources
L_MENU = "Sizi ana menüye yönlendiriyorum."
L_MENU_FAIL = "Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum."
L_NO_CARD = "Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum."
L_AGENT = "Sizi müşteri temsilcimize aktarıyorum."
L_PAY = "Borç ödeme işleminiz için sizi müşteri temsilcimize aktarıyorum."
L_DISPUTE = "Bu konuda size müşteri temsilcimiz yardımcı olacak, sizi aktarıyorum."
L_ERROR = "Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum."
L_WEEK_ERROR = "Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum."
L_LANG = "Sizi ana menüye aktarıyorum."
L_OOS_Q = "Size bu konuda yardımcı olamıyorum. Sizi ana menüye aktarmamı ister misiniz?"
L_SILENCE = "Sesinizi alamadığım için görüşmeyi sonlandırıyorum."
L_THIRD = ("Güvenlik nedeniyle işlemleri yalnızca kendi kartlarınız için yapabiliyorum. "
           "Kart sahibinin kendi kimliğiyle giriş yapabilmesi için sizi ana menüye yönlendiriyorum.")

# ---------------------------------------------------------------- shared code (never double braces)
COMMON = r'''
import re, json, datetime
from decimal import Decimal, ROUND_HALF_UP
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
CUR = [('debtTL', 'Türk Lirası'), ('debtUSD', 'Dolar'), ('debtEUR', 'Euro'), ('debtGBP', 'İngiliz Sterlini')]
UNIT = dict(debtTL=('Türk Lirası', 'lira', 'kuruş'), debtUSD=('dolar', 'dolar', 'sent'), debtEUR=('Euro', 'Euro', 'sent'), debtGBP=('İngiliz Sterlini', 'İngiliz Sterlini', 'peni'))
def w3(n):
    h, t, o = n // 100, (n // 10) % 10, n % 10
    out = []
    if h:
        out.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        out.append(TENS[t])
    if o:
        out.append(ONES[o])
    return ' '.join(out)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for size, name in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q = n // size
        if q:
            if size == 1000 and q == 1:
                parts.append('bin')
            else:
                parts.append(w3(q) if q < 1000 else words(q))
                parts.append(name)
            n = n % size
    if n:
        parts.append(w3(n))
    return ' '.join(p for p in parts if p)
def dec(x):
    try:
        return Decimal(str(x)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except Exception:
        return Decimal('0')
def money(x, key):
    d = dec(x)
    whole = int(d)
    frac = int((d - whole) * 100)
    full, unit, sub = UNIT[key]
    if frac == 0:
        return words(whole) + ' ' + full
    return words(whole) + ' ' + unit + ' ' + words(frac) + ' ' + sub
def cop(phrase):
    p = str(phrase).rstrip()
    low = p.lower()
    vow = [ch for ch in low if ch in 'aeıioöuü']
    v = vow[-1] if vow else 'e'
    suf = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[v]
    d = 't' if low and low[-1] in 'fstkçşhp' else 'd'
    sep = "'" if (p[-1:].isdigit()) else ''
    return p + sep + d + suf + 'r'
def num_last_word(n):
    return words(n).split()[-1]
def pdate(s):
    s = str(s or '').strip()
    m = re.fullmatch(r'(\d{1,2})\.(\d{1,2})\.(\d{4})', s)
    if not m:
        return None
    try:
        return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    except Exception:
        return None
def sdate(d):
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)
def sdate_cop(d):
    w = num_last_word(d.year)
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year) + "'" + cop(w)[len(w):]
def today():
    s = str(vars.get('now') or '')
    m = re.match(r'(\d{4})-(\d{2})-(\d{2})', s)
    if m:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    return None
def digits_spoken(s):
    return ' '.join(DIG[int(ch)] for ch in str(s) if ch.isdigit())
def body_of(prefix):
    raw = vars.get(prefix + '_data')
    if isinstance(raw, str) and raw.strip().startswith('{'):
        try:
            raw = json.loads(raw)
        except Exception:
            raw = None
    if isinstance(raw, dict):
        return raw
    return None
def ok_rc(prefix):
    return str(vars.get(prefix + '_rc') or '').strip() == '1'
def jl(name):
    v = vars.get(name)
    if isinstance(v, list):
        return v
    try:
        v = json.loads(str(v or '[]'))
        return v if isinstance(v, list) else []
    except Exception:
        return []
def card_name(c):
    n = str(c.get('productName') or '').strip()
    if not n or len(n.split()) > 5 or len(n) > 40:
        return ''
    return n
def card_intro(c):
    n = card_name(c)
    base = 'Sonu ' + digits_spoken(c.get('cardNumberLast4') or '') + ' ile biten '
    return base + (n + ' ' if n else '')
def norm(s):
    s = str(s or '').replace('İ', 'i').replace('I', 'ı').lower()
    s = s.replace('yildiz', 'yıldız')
    return re.sub(r'\s+', ' ', re.sub(r'[^0-9a-zçğıöşü ]', ' ', s)).strip()
NUMW = dict(sıfır=0, bir=1, iki=2, üç=3, dört=4, beş=5, altı=6, yedi=7, sekiz=8, dokuz=9)
TENW = dict(on=10, yirmi=20, otuz=30, kırk=40, elli=50, altmış=60, yetmiş=70, seksen=80, doksan=90)
def said_digits(s):
    low = norm(s)
    out = ''
    toks = low.split()
    i = 0
    while i < len(toks):
        t = toks[i]
        if t.isdigit():
            out += t
        elif t in TENW:
            v = TENW[t]
            if i + 1 < len(toks) and toks[i + 1] in NUMW and NUMW[toks[i + 1]] > 0:
                v += NUMW[toks[i + 1]]
                i += 1
            out += str(v)
        elif t in NUMW:
            out += str(NUMW[t])
        i += 1
    return out
def names_list(cards):
    ns = []
    for c in cards:
        n = card_name(c) or ('sonu ' + digits_spoken(c.get('cardNumberLast4') or '') + ' ile biten kartınız')
        if n not in ns:
            ns.append(n)
    if len(ns) == 1:
        return ns[0]
    return ', '.join(ns[:-1]) + ' ve ' + ns[-1]
def examples(cards):
    ns = []
    for c in cards:
        n = card_name(c)
        if n and n not in ns:
            ns.append(n)
    return ns[:2]
def select_question(cards):
    ex = examples(cards)
    q = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
    if len(ex) == 2:
        q += ' Örneğin, ' + ex[0] + ' veya ' + ex[1] + ' diyebilirsiniz.'
    elif len(ex) == 1:
        q += ' Örneğin, ' + ex[0] + ' diyebilirsiniz.'
    return q
'''

INIT_CODE = r'''
try:
    vars['sel_tries'] = '0'
    vars['card_said'] = 'consumed'
    vars['next_step'] = 'consumed'
    vars['read_cards'] = '[]'
    vars['route'] = 'none'
    vars['say_text'] = ''
    vars['select_prompt'] = ''
    vars['sel_card_number'] = ''
    vars['cl_data'] = ''
    vars['cl_rc'] = ''
    vars['em_data'] = ''
    vars['em_rc'] = ''
    vars['week_choice'] = 0
    vars['confirm_tries'] = '0'
    vars['email_tries'] = '0'
    vars['week_tries'] = '0'
except Exception:
    pass
'''

AFTER_LIST_CODE = COMMON + r'''
try:
    d = body_of('cl')
    rc = str(vars.get('cl_rc') or '')
    cards = []
    if d and ok_rc('cl'):
        for c in d.get('cards') or []:
            if isinstance(c, dict) and c.get('cardNumber'):
                cards.append(dict(cardNumber=str(c.get('cardNumber')), cardNumberLast4=str(c.get('cardNumberLast4') or str(c.get('cardNumber'))[-4:]),
                                  productName=str(c.get('productName') or ''), isMainCard=(str(c.get('isMainCard')).lower() != 'false')))
        main = [c for c in cards if c['isMainCard']]
        vars['all_cards'] = json.dumps(cards, ensure_ascii=False)
        vars['main_cards'] = json.dumps(main, ensure_ascii=False)
