            pat = num.replace(' ', '')
            if len(pat) != len(dgs):
                return False
            return all(p == '*' or p == q for p, q in zip(pat, dgs))
        seg = num[-len(dgs):]
        return all(p == '*' or p == q for p, q in zip(seg, dgs))
    chosen = None
    if len(dg) >= 4:
        dgs = dg if len(dg) >= 15 else dg[-6:] if len(dg) >= 6 else dg[-4:]
        hits = [c for c in pool if tail_match(c, dgs)]
        if len(hits) == 1:
            chosen = hits[0]
        elif len(hits) > 1:
            vars['sel_pool'] = json.dumps(hits, ensure_ascii=False)
            if len(dgs) >= 15:
                fail('Söylediğiniz numarayla eşleşen tek bir kart bulamadım. Kart numaranızı tekrar söyler misiniz?')
            elif len(dgs) >= 6:
