def all_codes(wf):
    out = {}
    for k, n in list(wf["nodes"].items()) + list(wf["global_nodes"].items()):
        for a in n.get("pre_actions", []):
            fn = a["function"]
            if fn["handler"] == "__function__:code_exec":
                out[k] = fn["parameters"]["properties"]["code"]["default"]
            for h in ("pre_process_code", "post_process_code"):
                if a.get(h):
                    out[k + ":" + h] = a[h]
    return out


